// Which grammar highlights a file. The tables come from GitHub Linguist
// (generated by scripts/gen-languages.mjs), so files are recognized the way
// GitHub recognizes them.

import languages from "./languages.json";

const filenames: Record<string, string> = languages.filenames;
const extensions: Record<string, string> = languages.extensions;
const interpreters: Record<string, string> = languages.interpreters;

/**
 * The Shiki grammar id for `path`, or `null` for plain text. `firstLine` is
 * the file's first line when known, for scripts named only by a shebang.
 */
export function languageFor(path: string, firstLine?: string): string | null {
  const name = path.slice(path.lastIndexOf("/") + 1);
  const byName = filenames[name];
  if (byName) return byName;

  // Longest extension first: `a.blade.php` before `a.php`.
  const lower = name.toLowerCase();
  for (let dot = lower.indexOf(".", 1); dot !== -1; dot = lower.indexOf(".", dot + 1)) {
    const byExt = extensions[lower.slice(dot + 1)];
    if (byExt) return byExt;
  }

  return firstLine === undefined ? null : shebangLanguage(firstLine);
}

/** `#!/usr/bin/env node`, `#!/bin/bash -e`, `#!/usr/bin/python3.12`. */
function shebangLanguage(line: string): string | null {
  const match = /^#!\s*(\S+)(?:\s+(?:-\S+\s+)*(\S+))?/.exec(line);
  if (!match) return null;
  let program = match[1].slice(match[1].lastIndexOf("/") + 1);
  if (program === "env" && match[2]) program = match[2];
  return interpreters[program] ?? interpreters[program.replace(/[\d.]+$/, "")] ?? null;
}
